import { data } from '@takaro/helpers';
import { readConfig, getMarketRow, parseMarket, currentPrice, lastChangePct, formatAmount, formatPct, requireEconomy } from './stx-helpers.js';

async function main() {
  const { pog, gameServerId, module: mod } = data;
  const cfg = readConfig(mod.userConfig);
  const { prefix, currency } = await requireEconomy(gameServerId);
  const market = parseMarket(await getMarketRow(gameServerId, mod.moduleId));

  if (cfg.stocks.length === 0) {
    await pog.pm('No stocks are listed right now.');
    return;
  }
  await pog.pm(`Stock market (prices in ${currency}):`);
  for (const stock of cfg.stocks) {
    const price = currentPrice(stock, market, cfg);
    await pog.pm(`${stock.id} ${stock.name}: ${formatAmount(price)} (${formatPct(lastChangePct(stock.id, market))})`);
  }
  await pog.pm(`Use ${prefix}stock <ticker>, ${prefix}buy <ticker> <shares>, ${prefix}sell <ticker> <shares|all>, ${prefix}portfolio.`);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, priceBounds, lastChangePct, getPortfolioRow, parsePortfolio,
  formatAmount, formatPct, requireEconomy, DRIVER_TEXT,
} from './stx-helpers.js';

async function main() {
  const { pog, gameServerId, arguments: args, module: mod } = data;
  const cfg = readConfig(mod.userConfig);
  const { prefix, currency } = await requireEconomy(gameServerId);
  const market = parseMarket(await getMarketRow(gameServerId, mod.moduleId));

  const stock = findStock(args.ticker, cfg, market);
  if (!stock) {
    const list = cfg.stocks.map((s) => s.id).join(', ');
    throw new TakaroUserError(`Usage: ${prefix}stock <ticker>. Tickers: ${list || 'none'}.`);
  }

  await pog.pm(`${stock.id} ${stock.name}: ${formatAmount(stock.price)} ${currency} (${formatPct(lastChangePct(stock.id, market))} last update).`);
  if (stock.delisted) {
    await pog.pm('This stock is no longer listed. You can still sell it at this price, but not buy it.');
  } else {
    const { floor, ceiling } = priceBounds(stock, cfg);
    await pog.pm(`Moves with: ${DRIVER_TEXT[stock.driver]}. Base ${formatAmount(stock.basePrice)}, range ${formatAmount(floor)} to ${formatAmount(ceiling)}.`);
  }
  const history = (market.stocks[stock.id] && Array.isArray(market.stocks[stock.id].history)) ? market.stocks[stock.id].history : [];
  if (history.length > 1) {
    await pog.pm(`Last prices: ${history.slice(-cfg.historyLength).map(formatAmount).join(', ')}`);
  }

  const portfolio = parsePortfolio(await getPortfolioRow(gameServerId, mod.moduleId, pog.playerId));
  const h = portfolio.holdings[stock.id];
  if (h) {
    await pog.pm(`You hold ${formatAmount(h.shares)} shares, worth ${formatAmount(h.shares * stock.price)} ${currency}.`);
  }
  const feeText = cfg.feePercent > 0 || cfg.minFee > 0 ? `Fee ${cfg.feePercent}% per trade (min ${cfg.minFee}).` : 'No trade fee.';
  await pog.pm(feeText);
}

await main();

import { data, takaro, TakaroUserError } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, getPortfolioRow, parsePortfolio, saveVar, feeFor, maxSharesFor,
  parseShares, withTradeLock, formatAmount, formatMinutes, requireEconomy, PORTFOLIO_KEY,
} from './stx-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const moduleId = mod.moduleId;
  const cfg = readConfig(mod.userConfig);
  const { prefix, currency } = await requireEconomy(gameServerId);
  const usage = `Usage: ${prefix}buy <ticker> <shares>. Example: ${prefix}buy ${cfg.stocks[0] ? cfg.stocks[0].id : 'DEF'} 5`;

  const market = parseMarket(await getMarketRow(gameServerId, moduleId));
  const stock = findStock(args.ticker, cfg, market);
  if (!stock) throw new TakaroUserError(usage);
  if (stock.delisted) throw new TakaroUserError(`${stock.id} is no longer listed. You can only sell it.`);
  const shares = parseShares(args.amount);
  if (shares === null || shares === 'all') throw new TakaroUserError(usage);

  await withTradeLock(gameServerId, moduleId, pog.playerId, async () => {
    const row = await getPortfolioRow(gameServerId, moduleId, pog.playerId);
    const portfolio = parsePortfolio(row);
    const held = portfolio.holdings[stock.id] ? portfolio.holdings[stock.id].shares : 0;
    const max = maxSharesFor(cfg, pog);
    if (held + shares > max) {
      throw new TakaroUserError(`You can hold at most ${formatAmount(max)} shares of ${stock.id}. You have ${formatAmount(held)}.`);
    }

    const value = stock.price * shares;
    const fee = feeFor(value, cfg, pog);
    const total = value + fee;
    const wallet = Math.floor(Number(pog.currency) || 0);
    if (total > wallet) {
      throw new TakaroUserError(`That costs ${formatAmount(total)} ${currency} (incl. fee ${formatAmount(fee)}). You have ${formatAmount(wallet)}.`);
    }

    try {
      await takaro.playerOnGameserver.playerOnGameServerControllerDeductCurrency(gameServerId, pog.playerId, {
        currency: total,
        reason: `Stock buy ${shares} ${stock.id}`,
      });
    } catch (err) {
      console.error(`stock-exchange: deduct failed: ${err}`);
      throw new TakaroUserError(`Could not take ${formatAmount(total)} ${currency}. Do you have enough?`);
    }

    const now = new Date().toISOString();
    const prev = portfolio.holdings[stock.id];
    portfolio.holdings[stock.id] = {
      shares: held + shares,
      cost: (prev ? prev.cost : 0) + total,
      holdSince: prev && prev.holdSince ? prev.holdSince : now,
      lastBuyAt: now,
    };
    portfolio.feesPaid += fee;
    portfolio.trades += 1;
    portfolio.name = player.name;
    try {
      await saveVar(row, { gameServerId, moduleId, playerId: pog.playerId }, PORTFOLIO_KEY, portfolio);
    } catch (err) {
      console.error(`stock-exchange: saving buy failed, refunding: ${err}`);
      await takaro.playerOnGameserver.playerOnGameServerControllerAddCurrency(gameServerId, pog.playerId, {
        currency: total,
        reason: 'Stock buy refund',
      });
      throw new TakaroUserError('The market could not save your trade. Your currency was returned.');
    }

    await pog.pm(`Bought ${formatAmount(shares)} ${stock.id} at ${formatAmount(stock.price)} for ${formatAmount(value)} + fee ${formatAmount(fee)} = ${formatAmount(total)} ${currency}.`);
    const lockText = cfg.sellLockMinutes > 0 ? ` You can sell them in ${formatMinutes(cfg.sellLockMinutes * 60000)}.` : '';
    await pog.pm(`You now hold ${formatAmount(held + shares)} ${stock.id}.${lockText}`);
  });
}

await main();

import { data, takaro, TakaroUserError } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, getPortfolioRow, parsePortfolio, saveVar, feeFor, parseShares,
  withTradeLock, formatAmount, formatMinutes, signed, requireEconomy, PORTFOLIO_KEY,
} from './stx-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const moduleId = mod.moduleId;
  const cfg = readConfig(mod.userConfig);
  const { prefix, currency } = await requireEconomy(gameServerId);
  const usage = `Usage: ${prefix}sell <ticker> <shares|all>. See ${prefix}portfolio for what you hold.`;

  const market = parseMarket(await getMarketRow(gameServerId, moduleId));
  const stock = findStock(args.ticker, cfg, market);
  const wanted = parseShares(args.amount);
  if (!stock || wanted === null) throw new TakaroUserError(usage);

  await withTradeLock(gameServerId, moduleId, pog.playerId, async () => {
    const row = await getPortfolioRow(gameServerId, moduleId, pog.playerId);
    const portfolio = parsePortfolio(row);
    const before = JSON.parse(JSON.stringify(portfolio));
    const h = portfolio.holdings[stock.id];
    if (!h) throw new TakaroUserError(`You have no ${stock.id} shares.`);
    const shares = wanted === 'all' ? h.shares : wanted;
    if (shares > h.shares) throw new TakaroUserError(`You only have ${formatAmount(h.shares)} ${stock.id} shares.`);

    if (cfg.sellLockMinutes > 0 && h.lastBuyAt) {
      const left = Date.parse(h.lastBuyAt) + cfg.sellLockMinutes * 60000 - Date.now();
      if (left > 0) throw new TakaroUserError(`You just bought ${stock.id}. You can sell it in ${formatMinutes(left)}.`);
    }

    const value = stock.price * shares;
    const fee = Math.min(value, feeFor(value, cfg, pog));
    const payout = value - fee;
    const costPart = Math.round((h.cost * shares) / h.shares);
    const profit = payout - costPart;

    // Write the portfolio BEFORE paying: a second sell (or a crash) can never pay twice for the same shares.
    if (shares === h.shares) {
      delete portfolio.holdings[stock.id];
    } else {
      portfolio.holdings[stock.id] = { ...h, shares: h.shares - shares, cost: h.cost - costPart };
    }
    portfolio.feesPaid += fee;
    portfolio.realized += profit;
    portfolio.trades += 1;
    portfolio.name = player.name;
    const scope = { gameServerId, moduleId, playerId: pog.playerId };
    const rowId = await saveVar(row, scope, PORTFOLIO_KEY, portfolio);

    if (payout > 0) {
      try {
        await takaro.playerOnGameserver.playerOnGameServerControllerAddCurrency(gameServerId, pog.playerId, {
          currency: payout,
          reason: `Stock sell ${shares} ${stock.id}`,
        });
      } catch (err) {
        console.error(`stock-exchange: payout failed, restoring shares: ${err}`);
        await saveVar({ id: rowId }, scope, PORTFOLIO_KEY, before);
        throw new TakaroUserError('The market could not pay you right now. Your shares were not sold.');
      }
    }

    await pog.pm(`Sold ${formatAmount(shares)} ${stock.id} at ${formatAmount(stock.price)} for ${formatAmount(value)} - fee ${formatAmount(fee)} = ${formatAmount(payout)} ${currency}.`);
    const left = portfolio.holdings[stock.id] ? portfolio.holdings[stock.id].shares : 0;
    await pog.pm(`Profit on these shares: ${signed(profit)} ${currency}. You still hold ${formatAmount(left)} ${stock.id}.`);
  });
}

await main();

import { data } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, getPortfolioRow, parsePortfolio, formatAmount, formatMinutes,
  signed, requireEconomy,
} from './stx-helpers.js';

async function main() {
  const { pog, gameServerId, module: mod } = data;
  const cfg = readConfig(mod.userConfig);
  const { prefix, currency } = await requireEconomy(gameServerId);
  const market = parseMarket(await getMarketRow(gameServerId, mod.moduleId));
  const portfolio = parsePortfolio(await getPortfolioRow(gameServerId, mod.moduleId, pog.playerId));

  const ids = Object.keys(portfolio.holdings).sort();
  if (ids.length === 0) {
    await pog.pm(`You own no shares. See ${prefix}market and buy with ${prefix}buy <ticker> <shares>.`);
    if (portfolio.trades > 0) {
      await pog.pm(`Realized profit so far: ${signed(portfolio.realized)} ${currency}. Fees paid: ${formatAmount(portfolio.feesPaid)}.`);
    }
    return;
  }

  let totalValue = 0;
  let totalCost = 0;
  await pog.pm(`Your portfolio (${currency}):`);
  const now = Date.now();
  for (const id of ids) {
    const h = portfolio.holdings[id];
    const stock = findStock(id, cfg, market);
    const price = stock ? stock.price : 0;
    const value = price * h.shares;
    totalValue += value;
    totalCost += h.cost;
    const notes = [];
    if (cfg.sellLockMinutes > 0 && h.lastBuyAt) {
      const left = Date.parse(h.lastBuyAt) + cfg.sellLockMinutes * 60000 - now;
      if (left > 0) notes.push(`sell in ${formatMinutes(left)}`);
    }
    if (cfg.holdStreakDays > 0 && h.holdSince) {
      const days = (now - Date.parse(h.holdSince)) / 86400000;
      if (days >= cfg.holdStreakDays) notes.push('hold bonus');
      else notes.push(`hold bonus in ${Math.ceil(cfg.holdStreakDays - days)}d`);
    }
    if (stock && stock.delisted) notes.push('delisted');
    const noteText = notes.length ? ` [${notes.join(', ')}]` : '';
    await pog.pm(`${id}: ${formatAmount(h.shares)} x ${formatAmount(price)} = ${formatAmount(value)} (${signed(value - h.cost)})${noteText}`);
  }
  await pog.pm(`Total value ${formatAmount(totalValue)}, paid ${formatAmount(totalCost)}, open profit ${signed(totalValue - totalCost)}.`);
  await pog.pm(`Realized profit ${signed(portfolio.realized)}. Fees paid ${formatAmount(portfolio.feesPaid)}. Fees fund the dividends.`);
}

await main();

import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, listPortfolioRows, parsePortfolio, getDividendsRow, parseDividends,
  poolFrom, formatAmount, requireEconomy,
} from './stx-helpers.js';

async function main() {
  const { pog, gameServerId, module: mod } = data;
  if (!checkPermission(pog, 'STOCK_ADMIN')) {
    throw new TakaroUserError('You do not have permission to see market stats.');
  }
  const cfg = readConfig(mod.userConfig);
  const { currency } = await requireEconomy(gameServerId);
  const market = parseMarket(await getMarketRow(gameServerId, mod.moduleId));
  const rows = await listPortfolioRows(gameServerId, mod.moduleId);
  const portfolios = rows.map((r) => ({ playerId: r.playerId, ...parsePortfolio(r) }));
  const dividends = parseDividends(await getDividendsRow(gameServerId, mod.moduleId));
  const { fees, paid, pool } = poolFrom(portfolios, dividends);

  let shares = 0;
  let value = 0;
  const holders = [];
  for (const p of portfolios) {
    let v = 0;
    for (const [id, h] of Object.entries(p.holdings)) {
      const stock = findStock(id, cfg, market);
      shares += h.shares;
      v += (stock ? stock.price : 0) * h.shares;
    }
    value += v;
    if (v > 0) holders.push({ name: p.name ?? 'unknown', value: v });
  }
  holders.sort((a, b) => b.value - a.value);
  const traders = portfolios.filter((p) => p.trades > 0).length;

  await pog.pm(`Market: ${traders} traders, ${holders.length} holders, ${formatAmount(shares)} shares worth ${formatAmount(value)} ${currency}.`);
  await pog.pm(`Fees in ${formatAmount(fees)}. Dividends out ${formatAmount(paid)} in ${dividends.runs} run${dividends.runs === 1 ? '' : 's'}. Fee pool now ${formatAmount(pool)}.`);
  if (holders.length) {
    await pog.pm(`Top holders: ${holders.slice(0, 3).map((h) => `${h.name} ${formatAmount(h.value)}`).join(', ')}.`);
  }
  const l = market.last;
  await pog.pm(
    `Last update #${market.tick}: kills ${l.kills ?? 0}, deaths ${l.deaths ?? 0}, travel ${l.travel ?? 0}, online ${l.players ?? 0}.`,
  );
}

await main();

