import { data } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, saveVar, takeSignals, countOnline, signalDelta, nextPrice, currentPrice,
  broadcast, getServerTexts, formatAmount, formatPct, DRIVER_TEXT, MARKET_KEY,
} from './stx-helpers.js';

const AVG_WEIGHT = 0.3;

async function main() {
  const { gameServerId, module: mod } = data;
  const moduleId = mod.moduleId;
  const cfg = readConfig(mod.userConfig);
  const { economyEnabled } = await getServerTexts(gameServerId);
  if (!economyEnabled) {
    console.log('stock-exchange: economy disabled, prices not updated');
    return;
  }

  const row = await getMarketRow(gameServerId, moduleId);
  const market = parseMarket(row);
  const signals = await takeSignals(gameServerId, moduleId);
  signals.players = await countOnline(gameServerId);

  const deltas = {};
  const avg = { ...market.avg };
  for (const [signal, value] of Object.entries(signals)) {
    const prevAvg = Number(avg[signal]);
    deltas[signal] = signalDelta(value, Number.isFinite(prevAvg) ? prevAvg : NaN);
    avg[signal] = Number.isFinite(prevAvg) ? prevAvg + AVG_WEIGHT * (value - prevAvg) : value;
  }

  const moves = [];
  const stocks = { ...market.stocks };
  for (const stock of cfg.stocks) {
    const prev = currentPrice(stock, market, cfg);
    const delta = stock.driver === 'random' ? 0 : deltas[stock.driver] ?? 0;
    const { price, changePct, signalPct } = nextPrice(stock, prev, delta, cfg, Math.random());
    const old = stocks[stock.id] && Array.isArray(stocks[stock.id].history) ? stocks[stock.id].history : [prev];
    const history = [...old, price].slice(-Math.max(cfg.historyLength, 2));
    stocks[stock.id] = { name: stock.name, price, prev, changePct: Math.round(changePct * 10) / 10, history };
    moves.push({ stock, price, changePct, signalPct });
  }

  // Prices are saved first; news goes out only after the move, so nobody can trade on it in advance.
  const next = {
    stocks,
    avg,
    last: signals,
    tick: market.tick + 1,
    lastTickAt: new Date().toISOString(),
  };
  await saveVar(row, { gameServerId, moduleId }, MARKET_KEY, next);
  console.log(`stock-exchange: tick ${next.tick} signals ${JSON.stringify(signals)} moves ${moves.map((m) => `${m.stock.id}=${m.price}`).join(' ')}`);

  if (cfg.newsMinMovePercent <= 0 || cfg.maxNewsLines <= 0) return;
  const news = moves
    .filter((m) => Math.abs(m.changePct) >= cfg.newsMinMovePercent)
    .sort((a, b) => Math.abs(b.changePct) - Math.abs(a.changePct))
    .slice(0, cfg.maxNewsLines);
  for (const m of news) {
    const dir = m.changePct > 0 ? 'up' : 'down';
    let why = '';
    if (m.stock.driver !== 'random' && Math.sign(m.signalPct) === Math.sign(m.changePct) && Math.abs(m.signalPct) >= 1) {
      why = m.signalPct > 0 ? ` after more ${DRIVER_TEXT[m.stock.driver]} than usual` : ` after fewer ${DRIVER_TEXT[m.stock.driver]} than usual`;
    }
    await broadcast(gameServerId, `Market news: ${m.stock.name} (${m.stock.id}) ${dir} ${formatPct(Math.abs(m.changePct)).replace('+', '')} to ${formatAmount(m.price)}${why}.`);
  }
}

await main();

import { data, takaro } from '@takaro/helpers';
import {
  readConfig, getMarketRow, parseMarket, findStock, listPortfolioRows, parsePortfolio, getDividendsRow, parseDividends,
  poolFrom, saveVar, broadcast, getServerTexts, formatAmount, DIVIDENDS_KEY,
} from './stx-helpers.js';

async function main() {
  const { gameServerId, module: mod } = data;
  const moduleId = mod.moduleId;
  const cfg = readConfig(mod.userConfig);
  const { currency, economyEnabled } = await getServerTexts(gameServerId);
  if (!economyEnabled) {
    console.log('stock-exchange: economy disabled, no dividends');
    return;
  }

  const market = parseMarket(await getMarketRow(gameServerId, moduleId));
  const rows = await listPortfolioRows(gameServerId, moduleId);
  const portfolios = rows.map((r) => ({ playerId: r.playerId, ...parsePortfolio(r) }));
  const divRow = await getDividendsRow(gameServerId, moduleId);
  const ledger = parseDividends(divRow);
  const { pool } = poolFrom(portfolios, ledger);
  const budget = Math.floor((pool * cfg.dividendPayoutPercent) / 100);
  if (budget < 1) {
    console.log(`stock-exchange: fee pool ${pool}, nothing to pay`);
    return;
  }

  const now = Date.now();
  const streakMs = cfg.holdStreakDays * 86400000;
  const holders = [];
  for (const p of portfolios) {
    let weight = 0;
    let bonus = false;
    for (const [id, h] of Object.entries(p.holdings)) {
      const stock = findStock(id, cfg, market);
      if (!stock || stock.delisted) continue;
      let w = stock.price * h.shares;
      if (cfg.holdStreakDays > 0 && h.holdSince && now - Date.parse(h.holdSince) >= streakMs) {
        w *= 1 + cfg.holdBonusPercent / 100;
        bonus = true;
      }
      weight += w;
    }
    if (weight > 0 && p.playerId) holders.push({ ...p, weight, bonus });
  }
  const totalWeight = holders.reduce((s, h) => s + h.weight, 0);
  if (totalWeight <= 0) {
    console.log('stock-exchange: no shareholders, the pool stays');
    return;
  }

  const payouts = holders
    .map((h) => ({ ...h, amount: Math.floor((budget * h.weight) / totalWeight) }))
    .filter((h) => h.amount > 0);
  const total = payouts.reduce((s, h) => s + h.amount, 0);
  if (total < 1) return;

  // Book the payout first, so a crash halfway can never pay the same pool twice.
  await saveVar(divRow, { gameServerId, moduleId }, DIVIDENDS_KEY, {
    paid: ledger.paid + total,
    runs: ledger.runs + 1,
    lastAt: new Date().toISOString(),
    lastAmount: total,
    lastHolders: payouts.length,
  });

  for (const h of payouts) {
    try {
      await takaro.playerOnGameserver.playerOnGameServerControllerAddCurrency(gameServerId, h.playerId, {
        currency: h.amount,
        reason: 'Stock dividend',
      });
    } catch (err) {
      console.error(`stock-exchange: dividend to ${h.playerId} failed: ${err}`);
      continue;
    }
    try {
      const pog = (await takaro.playerOnGameserver.playerOnGameServerControllerGetOne(gameServerId, h.playerId)).data.data;
      if (pog && pog.online && pog.gameId) {
        const bonusText = h.bonus ? ' Hold bonus included.' : '';
        await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
          message: `Stock dividend: +${formatAmount(h.amount)} ${currency} from the trade fee pool.${bonusText}`,
          opts: { recipient: { gameId: pog.gameId } },
        });
      }
    } catch (err) {
      console.log(`stock-exchange: could not PM dividend to ${h.playerId}: ${err}`);
    }
  }
  await broadcast(gameServerId, `Stock dividends paid: ${formatAmount(total)} ${currency} to ${payouts.length} shareholders.`);
}

await main();

